-- ====================================================================================
--  企业人事管理系统 — 完整数据初始化脚本（data.sql）
-- ====================================================================================
--  数据库：enterprise_hr（InnoDB / utf8mb4 / utf8mb4_0900_ai_ci）
--  依赖：必须先执行 enterprise_hr_schema.sql 完成建库建表
-- ------------------------------------------------------------------------------------
--  用法（Windows 必须带 --default-character-set=utf8mb4，否则客户端走 gbk 中文会乱码）：
--      mysql -uroot -p123456 --default-character-set=utf8mb4 < enterprise_hr_schema.sql
--      mysql -uroot -p123456 --default-character-set=utf8mb4 < data.sql
--
--  脚本特性：
--    1. 可重复执行：开头清空全部业务表，不会产生重复数据
--    2. 全表显式指定主键 ID，输出稳定可复现
--    3. 覆盖全部 49 张表，按 9 大功能模块的真实业务场景组织
--
--  数据规模：
--    13 个部门 / 16 个岗位 / 50 名员工 / 51 个系统账号
--    50 份劳动合同 / 异动记录 / 员工附件
--    2 个月逐日考勤明细 + 月度汇总（由明细聚合，口径一致）/ 排班 / 假期余额
--    请假·加班·出差申请 / 2 个月薪资核算（含薪资条逐项明细）/ 社保公积金缴纳
--    招聘全链路：需求→职位发布→候选人→面试→Offer
--    培训全链路：讲师→课程→计划→报名签到→培训档案
--    绩效全链路：考核方案→指标→考核记录→绩效面谈
--    公告待办 / 通用审批流水 / 登录与操作日志
--
--  演示账号（密码统一 123456，BCrypt 存储；生产环境请立即修改）：
--    admin        系统管理员（非员工账号）
--    shenjianguo  总经理            zhengshiyi  技术总监
--    zhaoliu      产品总监          liufang     HR经理
--    wangqiang    财务经理          hanxue      前端开发部负责人
--    wangwu       测试与质量部负责人  huanglei    后端开发工程师（普通员工视角）
-- ====================================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
USE `enterprise_hr`;

