INSERT INTO `position` (`id`, `position_code`, `position_name`, `position_seq`, `job_level`, `dept_id`, `duty`, `requirement`, `headcount_limit`, `sort_no`, `status`) VALUES
  (1, 'P-TECH-001', 'Java开发工程师', 2, 'P4-P7', 5, '负责后端服务的需求分析、设计、开发与线上维护，参与技术方案评审', '本科及以上，计算机相关专业，3 年以上 Java 后端开发经验，熟悉 Spring 生态与 MySQL', 8, 1, 1),
