  (4, 'P-TECH-004', '架构师', 2, 'P7-P9', 5, '负责系统架构设计、技术选型、核心难点攻关与研发规范制定', '本科及以上，8 年以上研发经验，精通分布式架构与高并发系统设计', 3, 4, 1),
  (5, 'P-TECH-005', '技术总监', 1, 'M2-M4', 2, '统筹技术中心研发管理、团队建设、技术规划与跨部门协作', '本科及以上，10 年以上研发与管理经验，具备 30 人以上团队管理经历', 1, 5, 1),
  (6, 'P-PROD-001', '产品经理', 3, 'P5-P8', 8, '负责产品规划、需求调研分析、版本迭代管理与上线效果复盘', '本科及以上，5 年以上产品经验，有 B 端系统产品设计经验优先', 4, 6, 1),
  (7, 'P-PROD-002', '产品助理', 3, 'P3-P5', 8, '协助产品经理完成需求整理、原型绘制与产品文档编写', '本科及以上，1 年以上产品相关经验，逻辑清晰、文档能力强', 3, 7, 1),
  (8, 'P-PROD-003', '产品总监', 1, 'M2-M4', 3, '统筹产品中心规划、产品矩阵布局与产品团队管理', '本科及以上，10 年以上产品经验，具备完整产品线操盘经历', 1, 8, 1),
  (9, 'P-HR-001', 'HR专员', 3, 'P4-P6', 9, '负责招聘执行、员工关系、考勤统计与人事手续办理', '本科及以上，2 年以上 HR 相关工作经验，熟悉招聘与员工关系模块', 4, 9, 1),
  (10, 'P-HR-002', 'HR经理', 1, 'M1-M3', 9, '统筹人力资源各模块，制定并落地人力资源政策', '本科及以上，8 年以上 HR 经验，熟悉劳动法与人力六大模块', 1, 10, 1),
  (11, 'P-FIN-001', '会计', 3, 'P4-P7', 10, '负责账务处理、薪资核算、税务申报与财务报表编制', '本科及以上，3 年以上财务核算经验，持有中级会计师职称优先', 3, 11, 1),
  (12, 'P-FIN-002', '财务经理', 1, 'M1-M3', 10, '统筹财务管理、预算控制、资金规划与财务合规', '本科及以上，8 年以上财务经验，熟悉税务筹划与预算管理', 1, 12, 1),
  (13, 'P-ADM-001', '行政专员', 4, 'P3-P5', 11, '负责行政后勤、办公资产管理、会务与员工活动组织', '大专及以上，2 年以上行政相关经验，细致耐心、沟通能力强', 2, 13, 1),
  (14, 'P-MKT-001', '市场专员', 3, 'P4-P6', 12, '负责市场推广、品牌宣传、渠道运营与活动策划执行', '本科及以上，3 年以上市场推广经验，具备活动策划与渠道运营能力', 3, 14, 1),
