  (16, 'P-EXE-002', '总裁助理', 3, 'P4-P6', 13, '协助总经理处理日常事务、会议纪要、跨部门协调与行程安排', '本科及以上，3 年以上总裁办或助理岗位经验，文字与协调能力突出', 1, 16, 1);

