INSERT INTO `recruit_request` (`id`, `request_no`, `request_dept_id`, `position_id`, `position_name`, `recruit_count`, `hired_count`, `job_level`, `salary_min`, `salary_max`, `education_req`, `experience_years`, `job_description`, `job_requirement`, `hope_arrive_date`, `urgency`, `applicant_id`, `apply_time`, `approval_status`, `current_approver_id`, `status`) VALUES
  (1, 'RC20260701001', 5, 1, 'Java开发工程师', 3, 1, 'P4-P6', 14000.00, 22000.00, 3, 3, '1、负责集团人事管理系统后端服务的设计与开发；
2、参与需求评审、技术方案评审与代码评审；
3、负责线上问题定位与性能优化。', '本科及以上，计算机相关专业，3 年以上 Java 后端经验，熟悉 Spring Boot / MySQL / Redis，有中大型系统经验优先。', '2026-07-15', 2, 1004, '2026-07-01 09:30:00', 2, NULL, 1),
  (2, 'RC20260705002', 6, 2, '前端开发工程师', 2, 1, 'P4-P6', 13500.00, 21000.00, 3, 3, '1、负责管理系统前端页面开发与组件库建设；
2、与设计、产品协作还原交互稿；
3、持续优化页面性能与用户体验。', '本科及以上，计算机相关专业，3 年以上前端经验，熟练掌握 Vue3 / TypeScript / 工程化工具链。', '2026-07-20', 2, 1020, '2026-07-05 09:30:00', 2, NULL, 1),
  (3, 'RC20260710003', 7, 3, '测试工程师', 1, 1, 'P4-P5', 12000.00, 18000.00, 3, 2, '1、负责功能测试、接口自动化测试用例设计与执行；
2、参与版本发布质量把控与缺陷跟踪；
3、参与测试工具与平台建设。', '本科及以上，计算机相关专业，2 年以上测试经验，熟悉接口自动化与性能测试工具。', '2026-08-01', 1, 1026, '2026-07-10 09:30:00', 2, NULL, 2),
  (4, 'RC20260801004', 9, 9, 'HR专员', 1, 0, 'P3-P4', 9500.00, 13000.00, 3, 1, '1、负责招聘渠道运营与候选人初步筛选；
2、办理入离职手续与员工档案管理；
3、协助考勤统计与员工活动组织。', '本科及以上，人力资源相关专业，1 年以上招聘或员工关系经验，沟通表达能力强。', '2026-09-01', 3, 1036, '2026-08-01 09:30:00', 2, NULL, 1),
  (5, 'RC20260805005', 8, 6, '产品经理', 1, 0, 'P6-P7', 24000.00, 32000.00, 3, 5, '1、负责 B 端人事产品规划与需求调研；
2、主导版本迭代管理与上线效果复盘；
3、输出产品方案与原型文档。', '本科及以上，5 年以上 B 端产品经验，具备完整产品线规划经验，有 HR SaaS 背景优先。', '2026-09-15', 2, 1031, '2026-08-05 09:30:00', 2, NULL, 1),
  (6, 'RC20260810006', 12, 14, '市场专员', 1, 0, 'P4-P5', 13000.00, 18000.00, 3, 3, '1、负责市场推广活动策划与执行；
2、负责渠道运营与品牌内容产出；
3、跟踪投放效果并输出数据分析。', '本科及以上，市场营销相关专业，3 年以上市场推广经验，具备活动策划与渠道资源。', '2026-09-20', 1, 1042, '2026-08-10 09:30:00', 1, 1001, 1),
  (7, 'RC20260815007', 10, 11, '会计', 1, 0, 'P4-P5', 13000.00, 17000.00, 3, 3, '1、负责日常账务处理与凭证编制；
2、负责薪资核算与个税申报；
3、参与月度结账与财务报表编制。', '本科及以上，会计学 / 财务管理相关专业，3 年以上核算经验，持中级会计师职称优先。', '2026-10-01', 1, 1037, '2026-08-15 09:30:00', 1, 1001, 1),
  (8, 'RC20260820008', 2, 4, '架构师', 1, 0, 'P7-P8', 32000.00, 45000.00, 3, 8, '1、负责集团级技术架构设计与技术选型；
2、主导核心系统重构与高并发难点攻关；
3、制定研发规范并推动落地。', '本科及以上，8 年以上研发经验，精通分布式架构与高并发设计，具备 10 人以上技术团队管理经验。', '2026-10-15', 1, 1003, '2026-08-20 09:30:00', 0, NULL, 1);

