-- 绩效面谈：S/A 档做正向反馈与目标共创，C/D 档做绩效改进计划（PIP）
INSERT INTO `performance_interview` (`id`, `record_id`, `employee_id`, `interviewer_id`, `interview_time`, `interview_place`, `achievement`, `shortcoming`, `next_goal`, `employee_feedback`) VALUES
  (1, 1, 1001, 1001, '2026-04-25 15:00:00', '总部 A 座 12 层 1208 洽谈室', '目标完成情况：基本完成岗位职责，但部分指标达成率偏低，问题定位与推进节奏有待加强。；最终得分 72.60 分，等级 C。', '需加强需求理解与任务拆解能力，建议建立日报机制并接受主管双周辅导。', '下周期核心指标达成率提升至 90% 以上，缺陷密度下降 30%。', '希望公司能提供更清晰的晋升通道说明与对应的能力模型。'),
  (2, 2, 1002, 1001, '2026-04-22 15:00:00', '总部 A 座 12 层 1208 洽谈室', '目标完成情况：各项指标达成良好，在跨部门协作中主动补位，交付质量稳定。；最终得分 88.70 分，等级 A。', '在技术深度与影响力上仍有提升空间，建议输出更多可复用沉淀。', '下周期保持交付质量，同时在技术分享与文档沉淀上达成 2 项目标。', '当前工作量与节奏基本匹配，希望减少临时插入需求带来的返工。'),
  (3, 4, 1004, 1003, '2026-04-22 15:00:00', '总部 A 座 12 层 1208 洽谈室', '目标完成情况：关键指标未达成，交付延期较为集中，需要在方法与投入度上做系统性改进。；最终得分 64.06 分，等级 D。', '需制定 3 个月绩效改进计划，明确每周可量化目标，主管每周复盘一次。', '下周期完成 PIP 全部里程碑，季度末复评仍不达标将调整岗位。', '希望增加参与技术方案评审的机会，提升个人在团队中的影响力。'),
  (4, 5, 1005, 1004, '2026-04-25 15:00:00', '总部 A 座 12 层 1208 洽谈室', '目标完成情况：各项指标达成良好，在跨部门协作中主动补位，交付质量稳定。；最终得分 87.95 分，等级 A。', '在技术深度与影响力上仍有提升空间，建议输出更多可复用沉淀。', '下周期保持交付质量，同时在技术分享与文档沉淀上达成 2 项目标。', '希望公司能提供更清晰的晋升通道说明与对应的能力模型。'),
  (5, 7, 1007, 1004, '2026-04-25 15:00:00', '总部 A 座 12 层 1208 洽谈室', '目标完成情况：本周期关键指标全部超额达成，牵头完成核心模块重构，对团队交付效率提升贡献显著。；最终得分 92.19 分，等级 S。', '可承担更复杂的架构性任务，建议下一步承担小组技术负责人角色。', '下周期牵头一个跨部门重点项目，并培养 1 名后备骨干。', '希望能参加外部技术大会，拓宽视野。'),
  (6, 9, 1009, 1004, '2026-04-25 15:00:00', '总部 A 座 12 层 1208 洽谈室', '目标完成情况：基本完成岗位职责，但部分指标达成率偏低，问题定位与推进节奏有待加强。；最终得分 65.29 分，等级 C。', '需加强需求理解与任务拆解能力，建议建立日报机制并接受主管双周辅导。', '下周期核心指标达成率提升至 90% 以上，缺陷密度下降 30%。', '希望公司能提供更清晰的晋升通道说明与对应的能力模型。'),
  (7, 10, 1010, 1004, '2026-04-22 15:00:00', '总部 A 座 12 层 1208 洽谈室', '目标完成情况：各项指标达成良好，在跨部门协作中主动补位，交付质量稳定。；最终得分 86.59 分，等级 A。', '在技术深度与影响力上仍有提升空间，建议输出更多可复用沉淀。', '下周期保持交付质量，同时在技术分享与文档沉淀上达成 2 项目标。', '当前工作量与节奏基本匹配，希望减少临时插入需求带来的返工。'),
