INSERT INTO `notice` (`id`, `title`, `content`, `notice_type`, `publisher_id`, `publish_time`, `expire_time`, `target_scope`, `target_dept_ids`, `is_top`, `read_count`, `status`) VALUES
  (1, '关于 2026 年中秋节放假安排的通知', '各部门：
根据国务院办公厅通知精神，结合公司实际，现将 2026 年中秋节放假安排通知如下：
一、放假时间：9 月 25 日至 9 月 27 日，共 3 天；
二、请各部门提前做好工作安排与值班部署，确保业务连续性；
三、放假期间请保持通讯畅通。
特此通知。', 2, 1036, '2026-09-01 09:00:00', '2026-09-28 18:00:00', 1, NULL, 1, 46, 2),
  (2, '《员工考勤与休假管理办法》修订发布', '为规范考勤管理、保障员工休假权益，公司对《员工考勤与休假管理办法》进行了修订，自 2026 年 9 月 1 日起执行。
主要变化：
1、弹性班次适用范围扩大至产品与设计岗位；
2、迟到 30 分钟以上按半日事假处理；
3、年假结转有效期延长至次年 3 月 31 日。
请全体员工知悉并遵照执行。', 1, 1036, '2026-08-28 09:00:00', '2026-12-31 18:00:00', 1, NULL, 1, 44, 2),
  (3, '2026 年第三季度绩效考核工作启动', '各位同事：
2026 年 8 月绩效考核已于 9 月 1 日启动，请于 9 月 10 日前完成员工自评，9 月 20 日前主管完成评分，9 月 25 日前完成隔级复核。
逾期未提交将影响绩效工资核算，请务必按时完成。', 3, 1036, '2026-09-01 09:00:00', '2026-09-30 18:00:00', 1, NULL, 1, 46, 2),
  (4, '关于 2026 年下半年全员体检的通知', '公司将为全体员工安排年度健康体检，具体安排：
时间：9 月 15 日 - 9 月 30 日（工作日上午 8:00-11:00）
地点：美年大健康朝阳体检中心
请各部门在 9 月 10 日前汇总参检人员名单报行政部。体检当天需空腹。', 5, 1040, '2026-09-03 09:00:00', '2026-09-30 18:00:00', 1, NULL, 0, 41, 2),
  (5, '关于 2026 年国庆节后团建活动的通知', '公司定于 10 月 16 日 - 10 月 17 日组织全员团建活动，地点为怀柔雁栖湖拓展基地。
活动包含团队拓展、户外徒步与总结晚宴。请各部门提前协调工作，具体乘车安排另行通知。', 4, 1040, '2026-09-08 09:00:00', '2026-10-17 18:00:00', 1, NULL, 0, 24, 2),
  (6, '技术中心 Q3 技术分享会安排', '技术中心 Q3 技术分享会安排如下：
第一场：9 月 18 日 16:00 《高并发场景下的缓存设计》 主讲：冯超
第二场：9 月 25 日 16:00 《前端性能优化实践》 主讲：韩雪
地点：A 座 12 层多功能厅，欢迎其他部门同事参加。', 5, 1003, '2026-09-09 09:00:00', '2026-09-30 18:00:00', 2, '2,5,6,7', 0, 21, 2),
  (7, '关于规范加班申请与调休使用的说明', '近期发现部分员工存在先加班后补申请的情况，为规范管理，现明确：
1、加班须事前提交申请，经直属主管审批通过后方可执行；
2、工作日加班按 1.5 倍、休息日加班按 2 倍折算调休或计薪；
3、调休需在 3 个月内使用完毕，逾期作废。', 1, 1036, '2026-08-20 09:00:00', '2026-12-31 18:00:00', 1, NULL, 0, 39, 2),
  (8, '2026 年校园招聘正式启动', '2027 届校园招聘已正式启动，本次计划招聘 15 人，岗位涵盖研发、产品、测试与职能序列。
内部推荐成功入职的，推荐人可获得 2000 元推荐奖金。
简历请发送至 hr@enterprise.com 或直接联系人力资源部李娜。', 3, 1034, '2026-09-05 09:00:00', '2026-12-31 18:00:00', 1, NULL, 1, 43, 2),
  (9, '关于办公区消防演练的通知', '为提升全员消防安全意识，公司将于 9 月 20 日上午 10:00 组织消防疏散演练，预计时长 40 分钟。
演练期间请听从引导员指挥，按指定路线有序疏散至集合点。', 5, 1040, '2026-09-12 09:00:00', '2026-09-21 18:00:00', 1, NULL, 0, 18, 2),
  (10, '财务部关于 9 月报销单提交截止时间的提醒', '9 月费用报销单请于 9 月 25 日前提交至财务部，逾期将顺延至下月处理。
差旅报销需附出差申请单与发票原件，电子发票请打印后提交。', 3, 1037, '2026-09-11 09:00:00', '2026-09-26 18:00:00', 1, NULL, 0, 27, 2);

INSERT INTO `notice` (`id`, `title`, `content`, `notice_type`, `publisher_id`, `publish_time`, `expire_time`, `target_scope`, `target_dept_ids`, `is_top`, `read_count`, `status`) VALUES
  (11, '关于调整社保公积金缴费基数的通知', '根据北京市社保中心通知，2026 年度社保及公积金缴费基数上下限已调整，公司将于 9 月起按新基数申报，个人缴纳部分相应变动，请留意工资条明细。', 3, 1036, '2026-08-25 09:00:00', '2026-12-31 18:00:00', 1, NULL, 0, 0, 3),
  (12, '【草稿】2026 年度评优评先工作方案', '为激励先进、树立标杆，公司拟开展 2026 年度评优评先工作，设置优秀员工、优秀团队、技术创新奖等奖项。本方案尚在讨论中，待定稿后正式发布。', 5, 1036, NULL, NULL, 1, NULL, 0, 0, 1);

